insert into public.spark_subject_topics(subject_id,topic_id,section_id,title,description,sort_order,enabled,metadata)
values
('social-studies','b2-caribbean-groupings-development','b2-regional-development','20–21. Caribbean Groupings and Measuring Development','Locate major Caribbean groupings and use economic, social and human-development indicators intelligently.',10,true,'{"syllabus":{"section":"B","part":"ii","objectives":["20","21"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Identify the Greater Antilles, Lesser Antilles, Windward and Leeward groupings, the Eastern Caribbean and mainland Caribbean territories.","Explain what development means in Social Studies.","Explain the use and limitations of GDP/GNP, per-capita income, cost of living, literacy, life expectancy, infant mortality, social services and HDI.","Use several indicators together rather than treating one statistic as a complete measure of development."],"introduction":"The Caribbean is a region made up of island chains and mainland territories with different sizes, resources and development experiences. To compare development fairly, students need both geographic knowledge and the ability to read economic and social indicators without oversimplifying them.","sections":[{"title":"Major Caribbean groupings","bullets":["Greater Antilles: the larger islands in the northern Caribbean, including Cuba, Hispaniola, Jamaica and Puerto Rico.","Lesser Antilles: the arc of smaller islands extending through the eastern Caribbean.","Windward and Leeward Islands: sub-groupings within the Lesser Antilles. Exact historical usage can vary, so use the grouping expected by the map or syllabus context.","Eastern Caribbean: a practical regional grouping commonly used for territories in the eastern island chain.","Mainland Caribbean territories named in the syllabus include Belize, Guyana and Suriname."]},{"title":"What development means","paragraphs":["Development is a process of improving people''s economic and social conditions and expanding their opportunities and quality of life. Economic growth matters, but development is wider than the amount of money produced in an economy.","A territory can record rising national income while still facing unequal access to education, health care, housing or employment. That is why several indicators are needed."]},{"title":"Economic indicators","bullets":["Gross Domestic Product (GDP) measures the value of final goods and services produced within a country''s borders over a period.","Gross National Product or related national-income measures focus on income associated with nationals or residents according to the definition used by the source.","Per-capita income divides an income measure by population to create an average. It does not show how evenly income is shared.","Cost of living refers to the cost of purchasing the goods and services needed for everyday life. A high income can have less purchasing power where prices are high."]},{"title":"Social indicators","bullets":["Education and literacy indicate aspects of knowledge and access to learning.","Life expectancy provides a broad signal about health and living conditions.","Infant mortality measures deaths among infants in relation to live births and can reflect health, nutrition and service conditions.","Availability of social services shows whether people have access to services such as health, education, water and other public support."]},{"title":"Human Development Index","paragraphs":["The Human Development Index combines dimensions of health, education and income into a composite measure. It is useful for broader comparison than income alone, but no single index captures every dimension of people''s lives.","Good Social Studies analysis compares indicators, checks the year and source, and explains what each measure can and cannot tell us."]}],"keyPoints":["Development includes economic and social improvement, not income alone.","Per-capita figures are averages and can hide inequality.","Social indicators help reveal health, education and service conditions.","HDI combines health, education and income dimensions.","Caribbean groupings help students understand geography and regional cooperation."],"summary":"For development questions, avoid saying that the country with the highest GDP is automatically the ''most developed''. Identify the indicator, explain what it measures, then combine it with other evidence.","flashcards":[{"front":"What are the Greater Antilles?","back":"The larger northern Caribbean islands, including Cuba, Hispaniola, Jamaica and Puerto Rico."},{"front":"Name the mainland Caribbean territories in the syllabus.","back":"Belize, Guyana and Suriname."},{"front":"What does GDP measure?","back":"The value of final goods and services produced within a country''s borders over a period."},{"front":"What is per-capita income?","back":"An income measure divided by population to give an average per person."},{"front":"Why can per-capita income be misleading?","back":"An average can hide how unevenly income is distributed."},{"front":"What three broad dimensions does HDI combine?","back":"Health, education and income."},{"front":"Give two social development indicators.","back":"Examples: literacy, life expectancy, infant mortality or access to social services."}],"interactiveModels":[{"id":"b2-development-indicators","type":"social-studies","mode":"classify","title":"Development Indicator Sorter","categories":["Economic indicator","Social indicator","Composite indicator"],"items":[{"label":"Per-capita income","category":"Economic indicator"},{"label":"Life expectancy","category":"Social indicator"},{"label":"Literacy rate","category":"Social indicator"},{"label":"Cost of living","category":"Economic indicator"},{"label":"Human Development Index","category":"Composite indicator"},{"label":"Infant mortality rate","category":"Social indicator"}]}],"visualSources":[{"id":"caribbean-map-b2","title":"Blank Map of the Caribbean","creator":"NuclearVacuum","source":"Wikimedia Commons","license":"Public domain","url":"https://commons.wikimedia.org/wiki/File:BlankMap-Caribbean.svg","purpose":"Map practice for Caribbean groupings"}]}}'::jsonb),
('social-studies','b2-industries-ict','b2-regional-development','22–23. Caribbean Industries, Economic Contribution and ICT','Explain what helps Caribbean industries grow, how they contribute to development and how ICT changes the way they operate.',20,true,'{"syllabus":{"section":"B","part":"ii","objectives":["22","23"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Assess factors influencing agriculture, forestry, fishing, mining, tourism, manufacturing and cultural/creative industries.","Explain direct and indirect contributions to employment, foreign exchange, income and government revenue.","Explain linkages among industries.","Describe how ICT improves efficiency, markets, finance, research, entrepreneurship and worker education."],"introduction":"Caribbean economies are built from networks of industries rather than isolated sectors. A hotel buys agricultural produce, uses transportation, employs entertainers and pays utilities. A manufacturer depends on finance, ports, technology and skilled workers. Development improves when these linkages become stronger and more productive.","sections":[{"title":"What helps an industry develop","bullets":["Investment provides finance for equipment, buildings, training and expansion.","Markets provide customers. A firm with no reliable demand cannot grow simply because resources are available.","Infrastructure such as roads, ports, electricity, water and telecommunications reduces barriers to production.","Policies and regulations shape investment, safety, standards, taxation and environmental responsibilities.","Technology can improve productivity, communication and product quality.","Education and worker skills determine whether firms can use modern methods effectively."]},{"title":"How industries contribute","bullets":["Foreign exchange may be earned when goods or services are sold to overseas customers.","Direct employment is created inside the industry, such as farm managers, hotel workers, engineers or performers.","Indirect employment is created through linkages with suppliers and supporting services.","Businesses and workers generate income and spending in the wider economy.","Taxes, licences and other lawful charges can provide government revenue."]},{"title":"Industry linkages","paragraphs":["A tourism business may purchase food from farmers, furniture from manufacturers, transportation from local operators and entertainment from cultural workers. If more inputs are purchased locally, more of the spending can circulate through the domestic or regional economy.","Linkages do not happen automatically. Local producers must be able to meet quality, quantity, price and reliability requirements."]},{"title":"What ICT changes","bullets":["Faster communication and greater operational efficiency.","Access to customers and markets beyond the immediate territory.","Online booking, payment and other financial services.","Lower communication and transaction costs in some activities.","Research, product development and data analysis.","New opportunities for entrepreneurs and small firms.","Online learning and training for workers."]},{"title":"Technology also creates new risks","paragraphs":["Digital systems can create cybersecurity, privacy, skills and access challenges. A small business that moves sales online may reach more customers, but it also needs secure payment systems, reliable internet access and staff who can manage digital tools."]}],"keyPoints":["Investment, markets, infrastructure, policy, technology and skills affect industry growth.","Industries create direct and indirect employment.","Linkages allow one sector''s activity to support others.","ICT can widen markets and improve efficiency but also creates new skill and security needs."],"summary":"In assessment questions, choose one factor or contribution and explain the chain. For example: better port infrastructure → faster shipment → lower delays → improved reliability for exporters.","flashcards":[{"front":"Name three factors that influence industry development.","back":"Examples: investment, markets, infrastructure, regulation, technology or worker skills."},{"front":"What is direct employment?","back":"Jobs created within the industry being discussed."},{"front":"What is indirect employment?","back":"Jobs created in suppliers or services linked to another industry''s activity."},{"front":"What is an economic linkage?","back":"A connection where one industry buys from, sells to or supports another."},{"front":"How can ICT widen a market?","back":"Digital communication and commerce can connect firms with customers beyond their local area."},{"front":"Give one ICT risk for businesses.","back":"Examples: cybersecurity threats, privacy risks, weak connectivity or digital-skills gaps."}],"interactiveModels":[{"id":"b2-industry-linkage","type":"social-studies","mode":"choice","title":"Industry Linkage Lab","items":[{"context":"A hotel replaces imported vegetables with reliable purchases from local farmers.","prompt":"What is the clearest economic effect?","choices":["The hotel becomes a primary industry","A stronger tourism-agriculture linkage is created","All imports disappear","Government revenue must fall"],"correctIndex":1,"explanation":"The purchase connects tourism demand directly to domestic agricultural production."},{"context":"A craft producer begins selling online to Caribbean diaspora customers.","prompt":"Which ICT impact is most direct?","choices":["Access to a wider market","Elimination of production costs","No need for delivery services","Removal of all competition"],"correctIndex":0,"explanation":"Digital commerce can expand the geographic reach of customers."},{"context":"A fishing cooperative cannot keep products cold before export.","prompt":"Which development factor is most directly weak?","choices":["Cultural heritage","Infrastructure","Voting system","Population density"],"correctIndex":1,"explanation":"Cold storage and transport are infrastructure needed to preserve quality and reach markets."}]}]}}'::jsonb),
('social-studies','b2-development-challenges','b2-regional-development','24. Caribbean Development Challenges, Strategies and Justification','Analyse physical, economic and social development challenges and design strategies that address the actual cause of each problem.',30,true,'{"syllabus":{"section":"B","part":"ii","objectives":["24a","24b","24c"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Distinguish a hazard from a disaster.","Explain physical, economic and social challenges facing Caribbean development.","Propose realistic strategies for reducing or managing those challenges.","Justify strategies by linking them to causes, feasibility and the wider public good."],"introduction":"The Caribbean''s development challenges are connected. A hurricane is a physical hazard, but the scale of a disaster depends partly on where people build, how infrastructure is maintained, whether warnings reach communities and how quickly institutions can respond. Good Social Studies analysis therefore avoids treating every problem as unavoidable.","sections":[{"title":"Hazard versus disaster","paragraphs":["A hazard is a potentially damaging event or process. A disaster occurs when a hazard seriously disrupts a community and exceeds its ability to cope using its own resources.","Two territories can experience similar storms but different levels of loss because vulnerability, building quality, settlement patterns, preparedness and emergency capacity differ."]},{"title":"Physical challenges","bullets":["Hurricanes, floods, droughts, earthquakes, volcanic activity and tsunamis.","Vulnerability created or increased by settlement in exposed areas, weak buildings, environmental degradation or inadequate planning.","Disaster management and resilience, including preparation, response, recovery and risk reduction."]},{"title":"Economic challenges","bullets":["Small national markets and limited economies of scale.","Low production or productivity and lack of diversification.","Unemployment and underemployment.","Unequal distribution of resources among territories.","High debt burdens and high import costs.","Shortages of skilled workers, technology and investment capital.","Low-value exports and difficulty entering some external markets."]},{"title":"Social challenges","bullets":["Crime and violence can damage quality of life, investment and community stability.","Health crises can reduce productivity and place heavy demands on public systems.","Rapid migration into particular territories or communities may create new labour, housing and service pressures if planning does not keep pace."]},{"title":"From problem to strategy","paragraphs":["A strategy should fit the cause. If flooding is worsened by blocked drains and uncontrolled construction, a strategy may combine drainage maintenance, land-use planning and public education. If unemployment reflects a skills mismatch, targeted training linked to actual vacancies is more logical than a generic campaign.","To justify a strategy, explain why it should work, what resources it requires, who would implement it, possible limitations and why the likely benefits support the greater good."]}],"keyPoints":["A hazard becomes a disaster through the interaction of the event with exposure and vulnerability.","Caribbean development challenges can be physical, economic and social.","A strategy should address a specific cause or vulnerability.","Justification requires evidence, feasibility and a clear link between action and outcome."],"summary":"Use the structure problem → cause → strategy → justification. This makes both short answers and essays much stronger.","flashcards":[{"front":"What is a hazard?","back":"A potentially damaging event or process that can threaten people, property or the environment."},{"front":"What is a disaster?","back":"Serious disruption that causes losses beyond a community''s ability to cope with its own resources."},{"front":"Give one economic Caribbean development challenge.","back":"Examples: small markets, debt, unemployment, high import costs, low-value exports or limited capital."},{"front":"What makes a strategy well justified?","back":"It addresses the cause, is feasible and has a clear evidence-based benefit."},{"front":"What is economic diversification?","back":"Developing a wider range of productive activities rather than relying heavily on a few."}],"interactiveModels":[{"id":"b2-challenge-response","type":"social-studies","mode":"choice","title":"Build a Better Strategy","items":[{"context":"A coastal town floods repeatedly because drains are blocked and new buildings cover natural drainage areas.","prompt":"Which response best fits the causes?","choices":["Advertise the town overseas","Improve drainage maintenance and enforce land-use planning","Reduce school hours","Increase food imports"],"correctIndex":1,"explanation":"The response directly targets drainage and development practices that increase flood risk."},{"context":"Employers report vacancies for technicians while many job seekers lack the required certification.","prompt":"Which strategy best fits?","choices":["Targeted technical training linked to employers","Build more tourist beaches","Reduce all imports immediately","Stop collecting labour data"],"correctIndex":0,"explanation":"The evidence points to a skills mismatch, so targeted training addresses the identified constraint."},{"context":"A small economy relies heavily on one export whose world price is falling.","prompt":"Which long-term strategy is most relevant?","choices":["Economic diversification","Higher population density","Fewer business records","More dependence on the same product"],"correctIndex":0,"explanation":"Diversification can reduce vulnerability to shocks affecting a single export."}]}]}}'::jsonb),
('social-studies','b2-integration-drivers-history','b2-regional-development','25–26. Why Caribbean Integration Matters and How It Developed','Explain the forces promoting regional integration and trace major attempts from federation and free trade to modern regional arrangements.',40,true,'{"syllabus":{"section":"B","part":"ii","objectives":["25","26"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Explain geographic, cultural, economic, social and global factors promoting Caribbean integration.","Explain how disasters, climate risk and small markets can strengthen the case for cooperation.","Distinguish bilateral and multilateral agreements.","Outline major integration attempts including the West Indies Federation, CARIFTA, CARICOM, OECS, ACS and CSME."],"introduction":"Regional integration is the process of countries cooperating more closely and, in some areas, coordinating or combining policies and markets. Caribbean integration is shaped by geography, shared history and culture, small national markets, common risks and the need for a stronger collective position in the world economy.","sections":[{"title":"Why countries integrate","bullets":["Geographic closeness makes travel, trade and shared services possible, even though sea and air transport can also be expensive.","Common cultural and historical experiences can support a sense of regional identity.","Many territories face similar social and economic problems that may be easier to tackle together.","Globalisation and large trading blocs can reduce the bargaining power of very small individual markets.","Natural disasters, climate change and external economic shocks create shared vulnerabilities.","Communication technology allows faster regional cultural and commercial interaction.","Consumers can support regional production and businesses through informed purchasing and investment."]},{"title":"Bilateral and multilateral agreements","paragraphs":["A bilateral agreement involves two parties, usually two countries or states. A multilateral agreement involves several parties. Integration often requires multilateral arrangements because many territories are coordinating the same rules or objectives."]},{"title":"Major attempts","bullets":["West Indies Federation: an early political-federation attempt among British Caribbean territories.","CARIFTA: a free-trade association intended to expand regional trade.","CARICOM: the Caribbean Community, established to deepen cooperation and integration.","OECS: an organisation supporting close cooperation among participating Eastern Caribbean states.","ACS: an association linking states around the wider Caribbean.","CSME: the CARICOM Single Market and Economy, intended to deepen economic integration through movement of goods, services, capital, skilled labour and establishment rights within its framework."]},{"title":"Integration is a process, not one event","paragraphs":["Different organisations have different membership and objectives. Students should not treat CARICOM, OECS, ACS and CSME as interchangeable names. Learn what each arrangement is trying to achieve and the level of integration involved."]}],"keyPoints":["Small size, shared vulnerability and global competition can encourage integration.","Bilateral means two parties; multilateral means several.","West Indies Federation, CARIFTA, CARICOM, OECS, ACS and CSME are distinct stages or arrangements.","Integration can be political, economic or functional and does not require every country to participate in every arrangement in the same way."],"summary":"Learn the sequence and purpose, not just the abbreviations. When comparing organisations, state what kind of cooperation each one represents.","flashcards":[{"front":"What is regional integration?","back":"A process in which countries cooperate more closely and coordinate selected policies, markets or institutions."},{"front":"What is a bilateral agreement?","back":"An agreement involving two countries or parties."},{"front":"What is a multilateral agreement?","back":"An agreement involving several countries or parties."},{"front":"What was CARIFTA mainly designed to expand?","back":"Free trade among participating Caribbean territories."},{"front":"What does CARICOM stand for?","back":"Caribbean Community."},{"front":"What does CSME stand for?","back":"CARICOM Single Market and Economy."},{"front":"Why can small markets encourage integration?","back":"A larger regional market can improve scale, trade opportunities and bargaining power."}],"interactiveModels":[{"id":"b2-integration-sequence","type":"social-studies","mode":"choice","title":"Integration Timeline","items":[{"prompt":"Which sequence places these major developments in the correct general order?","choices":["CARICOM → CARIFTA → Federation → CSME","West Indies Federation → CARIFTA → CARICOM → CSME","CSME → Federation → CARICOM → CARIFTA","OECS → Federation → CARIFTA → CARICOM"],"correctIndex":1,"explanation":"The West Indies Federation preceded CARIFTA, which preceded CARICOM, with CSME representing a later stage of CARICOM economic integration."},{"prompt":"An agreement is signed by six Caribbean states. What type is it?","choices":["Bilateral","Multilateral","Domestic","Private"],"correctIndex":1,"explanation":"More than two state parties makes it a multilateral agreement."}]}]}}'::jsonb),
('social-studies','b2-regional-institutions','b2-regional-development','27. OECS, CARICOM, CSME, CCJ and Policy Harmonisation','Understand the different purposes of key regional institutions and what economic integration requires in practice.',50,true,'{"syllabus":{"section":"B","part":"ii","objectives":["27"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Outline major objectives of the OECS and CARICOM.","Explain key CSME objectives including movement of goods, services, capital and skilled labour and right of establishment.","Explain the CCJ''s role in settling disputes connected to regional arrangements.","Explain why immigration, tax, monetary, trade, company and sectoral policies may need harmonisation."],"introduction":"Regional integration becomes real only when institutions, laws and policies support it. Memorising acronyms is not enough. Students should understand what each body is intended to do and how its work affects people, businesses and governments.","sections":[{"title":"OECS and CARICOM","paragraphs":["The syllabus emphasises functional cooperation, economic integration and coordinated foreign-policy objectives. Functional cooperation means countries work together in practical areas such as education, health and disaster response instead of duplicating every service separately."]},{"title":"CSME","bullets":["Movement of goods and services within the agreed framework.","Right of establishment for qualifying businesses and economic activity.","Movement of capital.","Movement of eligible categories of skilled labour under applicable arrangements.","Support mechanisms such as the CARICOM Development Fund for disadvantaged countries, regions or sectors within the integration process."]},{"title":"Caribbean Court of Justice","paragraphs":["The syllabus highlights the CCJ''s role in settling disputes among member states connected to regional agreements. The CCJ also has broader judicial roles that depend on jurisdiction and treaty arrangements, but students should keep the exam response tied to the question asked."]},{"title":"Why harmonisation matters","paragraphs":["If countries want a shared economic space, major policy differences can create obstacles. Harmonisation means bringing selected policies or laws into greater consistency. The syllabus identifies immigration, fiscal policy, monetary policy, external trade, customs/company legislation and sectoral policies such as agriculture, manufacturing and fisheries.","Harmonisation does not mean every domestic rule becomes identical overnight. It means cooperating enough for agreed regional objectives to function."]}],"keyPoints":["Functional cooperation pools effort in practical regional services.","CSME seeks deeper economic integration through freer movement and establishment within agreed rules.","The CCJ supports interpretation and dispute settlement under relevant regional arrangements.","Policy harmonisation reduces legal and administrative barriers to integration."],"summary":"Always match the organisation to its role. CARICOM is not the same thing as CSME, and the CCJ is not a trade organisation.","flashcards":[{"front":"What is functional cooperation?","back":"Countries pooling effort in practical areas such as health, education or disaster response."},{"front":"What does right of establishment mean in CSME?","back":"Qualifying persons or businesses may establish economic activity under agreed regional rules."},{"front":"Name two CSME movement objectives.","back":"Examples: goods, services, capital or eligible skilled labour."},{"front":"What is policy harmonisation?","back":"Bringing selected national policies or laws into greater consistency for shared regional objectives."},{"front":"What role of the CCJ is highlighted in integration?","back":"Interpreting relevant regional agreements and settling disputes under its treaty jurisdiction."},{"front":"What is the CARICOM Development Fund meant to address?","back":"Disadvantages affecting countries, regions or sectors within the integration process."}],"interactiveModels":[{"id":"b2-regional-body-match","type":"social-studies","mode":"classify","title":"Which Regional Mechanism?","categories":["Functional cooperation","CSME economic integration","CCJ dispute settlement","Policy harmonisation"],"items":[{"label":"Countries coordinate disaster-response capacity.","category":"Functional cooperation"},{"label":"A qualifying professional uses regional skilled-movement arrangements.","category":"CSME economic integration"},{"label":"Member states need a legal interpretation of an integration obligation.","category":"CCJ dispute settlement"},{"label":"Countries align selected customs rules to reduce barriers.","category":"Policy harmonisation"},{"label":"Regional health agencies coordinate a response to an outbreak.","category":"Functional cooperation"}]}]}}'::jsonb),
('social-studies','b2-integration-results-barriers-roles','b2-regional-development','28–30. Benefits, Successes, Barriers and Your Role in Integration','Evaluate what regional integration can achieve, why it remains difficult and how citizens, businesses, governments and media contribute.',60,true,'{"syllabus":{"section":"B","part":"ii","objectives":["28","29","30"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Analyse economic, social and international benefits of regional integration.","Recognise examples of functional and institutional successes.","Explain barriers including geography, transport costs, unequal resources, insularity, political will and competing national interests.","Explain roles of citizens, businesses, governments and mass media in integration."],"introduction":"Regional integration has produced real institutions and shared services, but it also faces persistent obstacles. A mature Social Studies answer can recognise both at the same time. Success does not mean every objective has been achieved; difficulty does not mean integration has achieved nothing.","sections":[{"title":"Potential benefits","bullets":["Larger markets for regional producers and service providers.","Expansion of trade and opportunities for investment.","Movement of goods, eligible labour and capital within agreed rules.","Cooperation in health, education, disaster response and other services.","Stronger international presence when states coordinate positions.","Potential improvements in competitiveness and quality of life when integration works effectively."]},{"title":"Examples of regional achievement","paragraphs":["The syllabus points students to examples such as UWI in tertiary education, CDB in development finance, CSME in trade and economic integration, CCJ in regional justice, CARPHA in health coordination, CDEMA in disaster management, CXC in regional certification, CARIFESTA in culture, regional sport and Caribbean tourism organisations.","Use these as evidence of particular forms of cooperation, not as proof that every aspect of integration is complete."]},{"title":"Why integration is difficult","bullets":["Island geography and the cost or limited availability of inter-regional transport.","Different levels of economic development and uneven resource distribution.","Competition among countries for investment, industries and markets.","National priorities that can conflict with regional commitments.","Insularity, meaning an overly narrow focus on one''s own territory at the expense of regional thinking.","Insufficient political will or slow implementation.","Lack of a common currency across the whole community and different policy systems.","Influence of external firms and markets on small economies."]},{"title":"Roles in the process","bullets":["Citizens can support regional businesses, remain informed, invest regionally, show solidarity and build a shared regional consciousness.","Businesses can improve quality and competitiveness, expand regional supply networks and create employment and investment opportunities.","Governments enact enabling laws, honour agreements, coordinate policies and explain integration to citizens.","Mass and social media can broadcast regional programming, share information and help citizens understand regional issues."]},{"title":"Evaluate with evidence","paragraphs":["A question asking whether integration has been successful should be answered by defining the area being assessed. Trade, disaster response, education and transport may show different results. Use evidence and criteria rather than a single sweeping judgement."]}],"keyPoints":["Integration can expand markets, trade, cooperation and international influence.","Regional institutions provide concrete examples of functional cooperation.","Transport, economic differences, national priorities and implementation challenges can slow integration.","Citizens, firms, governments and media all have roles.","Success should be assessed by a stated criterion and evidence."],"summary":"Use balanced, evidence-based analysis. State the benefit or barrier, explain the mechanism, and give a relevant regional example.","flashcards":[{"front":"Give one market benefit of regional integration.","back":"A larger combined market can create more customers and opportunities for regional firms."},{"front":"What is insularity in regional integration?","back":"An overly narrow focus on one''s own territory that weakens regional cooperation."},{"front":"How does CDEMA show functional cooperation?","back":"It coordinates regional disaster-management efforts and support."},{"front":"How does CXC support regional integration?","back":"It provides shared regional examination and certification systems."},{"front":"Give one role of regional businesses.","back":"Improve competitiveness, expand regional supply links and create investment or employment."},{"front":"Give one role of citizens in integration.","back":"Support regional producers, remain informed, invest regionally or show solidarity."},{"front":"Why should integration success be assessed by criteria?","back":"Different areas can show different levels of achievement; evidence must match the claim."}],"interactiveModels":[{"id":"b2-integration-evidence","type":"social-studies","mode":"classify","title":"Benefit, Barrier or Role?","categories":["Benefit/success","Barrier","Citizen/business/government/media role"],"items":[{"label":"Regional coordination for disaster response","category":"Benefit/success"},{"label":"High cost of travel between Caribbean territories","category":"Barrier"},{"label":"A government passes legislation required by a regional agreement","category":"Citizen/business/government/media role"},{"label":"A consumer deliberately considers competitive regional products","category":"Citizen/business/government/media role"},{"label":"Countries compete for the same foreign investment project","category":"Barrier"},{"label":"Shared regional certification through CXC","category":"Benefit/success"}]}]}}'::jsonb),
('social-studies','b2-tourism-integration','b2-regional-development','31–32. Tourism Products and Regional Integration','Compare Caribbean tourism products and explain how tourism can connect territories through marketing, transport, culture and regional linkages.',70,true,'{"syllabus":{"section":"B","part":"ii","objectives":["31","32"],"source":"CXC 14/G/SYLL 22"},"lesson":{"objectives":["Distinguish major Caribbean tourism products.","Explain how diversification can reduce over-reliance on one tourism product.","Describe ways tourism can promote regional integration.","Explain the roles of shared marketing, aviation hubs, communication links and regional travel.","Evaluate possible cooperation and competition among Caribbean destinations."],"introduction":"Caribbean tourism is more varied than the familiar image of sun, sea and sand. Nature tourism, health tourism, sports, heritage, music festivals and special events allow territories to build different tourism products. When countries connect these products, tourism can also support regional integration.","sections":[{"title":"Tourism products","bullets":["Sun, sea and sand tourism focuses strongly on beaches, climate and coastal recreation.","Nature or eco-tourism centres on natural environments and usually emphasises conservation and responsible use.","Health tourism involves travel connected to health, wellness or medical services.","Sports tourism is linked to participating in or watching sporting events and activities.","Cultural or heritage tourism centres on history, architecture, traditions, food, music, museums and cultural sites.","Music festivals and special events attract visitors around scheduled cultural, sporting or entertainment experiences."]},{"title":"Why diversify","paragraphs":["If several destinations sell almost the same product to the same market, they compete heavily on price and promotion. Diversification allows territories to develop experiences that match their natural, cultural and human resources and may spread visitor spending across more communities.","Diversification should still be sustainable. A new attraction that damages the resource visitors came to experience may undermine the long-term product."]},{"title":"Tourism as regional integration","bullets":["Market the Caribbean as a multi-country or single regional destination where appropriate.","Recognise and connect the distinctive tourism products offered by different territories.","Coordinate selected economic and marketing approaches.","Improve communication and travel linkages within the region.","Use aviation hubs and route connections to make multi-destination travel easier.","Promote domestic and regional travel by Caribbean residents as well as long-haul visitors."]},{"title":"Cooperation and competition can coexist","paragraphs":["Countries compete for visitors, investment and air routes, but they can also benefit when travellers see the region as connected. A visitor attending a festival in one territory may add another island to the same trip if flights, information and immigration processes make travel practical.","Regional coordination does not require every country to offer the same tourism product. In fact, distinctive products can make a combined regional itinerary more attractive."]}],"keyPoints":["Caribbean tourism products include beach, nature, health, sports, heritage, festivals and special events.","Diversification can widen markets and reduce dependence on one product.","Regional marketing and transport links can encourage multi-destination travel.","Cooperation can strengthen a regional product while territories continue to compete for visitors."],"summary":"For tourism-integration questions, connect the tourism idea to an integration mechanism such as shared marketing, transport, communication or complementary products.","flashcards":[{"front":"What is eco-tourism?","back":"Tourism centred on natural environments with emphasis on responsible use and conservation."},{"front":"What is heritage tourism?","back":"Travel focused on history, culture, traditions, architecture or heritage sites."},{"front":"Why diversify a tourism product?","back":"To reach different markets and reduce overdependence on one type of visitor experience."},{"front":"How can aviation hubs support integration?","back":"They can connect regional routes and make multi-destination travel easier."},{"front":"How can shared marketing promote integration?","back":"Countries can present complementary destinations as part of one regional travel experience."},{"front":"Can Caribbean destinations cooperate and compete at once?","back":"Yes. They may compete for visitors while sharing marketing, transport and regional linkages."}],"interactiveModels":[{"id":"b2-tourism-product-sort","type":"social-studies","mode":"classify","title":"Tourism Product Builder","categories":["Sun, sea and sand","Nature/eco","Health","Sports","Cultural/heritage","Festival/special event"],"items":[{"label":"Visitors travel to watch an international cricket series.","category":"Sports"},{"label":"Travellers visit a protected rainforest with trained local guides.","category":"Nature/eco"},{"label":"A trip is built around historic forts, museums and traditional food.","category":"Cultural/heritage"},{"label":"Visitors travel for a major annual music celebration.","category":"Festival/special event"},{"label":"A wellness resort markets rehabilitation and spa services.","category":"Health"},{"label":"A beachfront resort package focuses on swimming and coastal recreation.","category":"Sun, sea and sand"}]}]}}'::jsonb)
insert into public.spark_subject_activity_catalog(subject_id,activity_key,activity_type,section_id,topic_id,title,route,evidence_weight,enabled,metadata)
